    def mostFares(self, n: int, rides: List[List[int]]) -> int:
        rs = sorted(rides, key=lambda x: x[1])
        end = [0] * len(rs)
        for i, (s, e, t) in enumerate(rs):
            prev = max((end[j] for j in range(i) if rs[j][1] <= s), default=0)
            end[i] = prev + e - s + t
        return max(end, default=0)

