function mostFares(n: number, rides: number[][]): number {
  const rs = rides.slice().sort((a, b) => a[1] - b[1]);
  const ends = rs.map(r => r[1]);
  const dp = new Array(rs.length + 1).fill(0); // dp[i] = best using the first i rides
  for (let i = 0; i < rs.length; i++) {
    const [s, e, t] = rs[i];
    // count of rides with end <= s
    let lo = 0, hi = i;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (ends[mid] <= s) lo = mid + 1; else hi = mid;
    }
    dp[i + 1] = Math.max(dp[i], dp[lo] + e - s + t);
  }
  return dp[rs.length];
}

