function mostFares(n: number, rides: number[][]): number {
  const byEnd: number[][][] = Array.from({ length: n + 1 }, () => []);
  for (const r of rides) byEnd[r[1]].push(r);
  const best = new Array(n + 1).fill(0);
  for (let p = 2; p <= n; p++) {
    best[p] = best[p - 1];
    for (const [s, , t] of byEnd[p]) best[p] = Math.max(best[p], best[s] + p - s + t);
  }
  return best[n];
}

